import { useState, useEffect } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Plus, Download, Upload, BarChart3, TrendingUp, Users, Award, Settings } from 'lucide-react';
import { initializeDatabase, getStatistics } from './lib/database';
import OverviewTab from './components/OverviewTab';
import PerformanceTab from './components/PerformanceTab';
import FinancialTab from './components/FinancialTab';
import DetailsTab from './components/DetailsTab';
import AwardTab from './components/AwardTab';
import AddInitiativeDialog from './components/AddInitiativeDialog';
import AddAwardPointDialog from './components/AddAwardPointDialog';
import EnhancedImportExport from './components/EnhancedImportExport';
import EnhancedOfflineStatus from './components/EnhancedOfflineStatus';
import OfflineBanner from './components/OfflineBanner';
import CacheManager from './components/CacheManager';
import PWAInstallPrompt from './components/PWAInstallPrompt';
import NotificationSystem from './components/NotificationSystem';
import AdvancedSettings from './components/AdvancedSettings';
import EnhancedDataManagement from './components/EnhancedDataManagement';
import DepartmentEvaluation from './components/DepartmentEvaluation';
import SiteAdministration from './components/SiteAdministration';
import LanguageToggle from './components/LanguageToggle';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';
import './App.css';

function AppContent() {
  const { translate: t, isRTL } = useLanguage();
  const [activeTab, setActiveTab] = useState('award');
  const [statistics, setStatistics] = useState({});
  const [showAddInitiative, setShowAddInitiative] = useState(false);
  const [showAddAwardPoint, setShowAddAwardPoint] = useState(false);
  const [showImportExport, setShowImportExport] = useState(false);
  const [showAdvancedSettings, setShowAdvancedSettings] = useState(false);
  const [showDataManagement, setShowDataManagement] = useState(false);
  const [showSiteAdmin, setShowSiteAdmin] = useState(false);
  const [showCacheManager, setShowCacheManager] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  useEffect(() => {
    const initApp = async () => {
      await initializeDatabase();
      await loadStatistics();
    };
    initApp();
  }, [refreshTrigger]);

  const loadStatistics = async () => {
    try {
      const stats = await getStatistics();
      setStatistics(stats);
    } catch (error) {
      console.error('Error loading statistics:', error);
    }
  };

  const handleDataUpdate = () => {
    setRefreshTrigger(prev => prev + 1);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 font-['Sharjah',sans-serif]" dir={isRTL ? 'rtl' : 'ltr'}>
      {/* Enhanced Header */}
      <header className="text-white shadow-xl relative overflow-hidden" style={{background: 'linear-gradient(135deg, var(--brand-orange) 0%, var(--brand-orange-dark) 50%, var(--brand-gray) 100%)'}}>
        <div className="absolute inset-0 bg-black/10"></div>
        <div className="container mx-auto px-6 py-6 relative z-10">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4 space-x-reverse">
              <div>
                <h1 className="text-2xl font-bold text-white">{t('system.title')}</h1>
                <p className="text-white/90 text-sm">{t('system.subtitle')}</p>
              </div>
            </div>
            <div className="flex items-center space-x-3 space-x-reverse">
              <LanguageToggle />
            </div>
          </div>
        </div>
      </header>

      {/* Offline Banner */}
      <OfflineBanner />

      {/* Enhanced Action Bar */}
      <div className="bg-gradient-to-r from-gray-50 to-gray-100 border-b border-gray-200 shadow-sm">
        <div className="container mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3 space-x-reverse">
              <Button 
                onClick={() => setShowDataManagement(true)}
                className="text-white shadow-lg hover:shadow-xl transition-all duration-300 hover:scale-105"
                style={{backgroundColor: 'var(--brand-orange)'}}
              >
                <Plus className="h-4 w-4 ml-2" />
                {t('action.dataManagement')}
              </Button>
              
              <Button 
                onClick={() => setShowImportExport(true)}
                className="text-white shadow-lg hover:shadow-xl transition-all duration-300 hover:scale-105"
                style={{backgroundColor: 'var(--brand-gray)'}}
              >
                <Upload className="h-4 w-4 ml-2" />
                {t('action.importExport')}
              </Button>
              
              <Button 
                onClick={() => setShowAdvancedSettings(true)}
                variant="outline"
                className="border-2 text-white transition-all duration-300 hover:scale-105"
                style={{borderColor: 'var(--brand-gray)', backgroundColor: 'var(--brand-gray-light)'}}
              >
                <Settings className="h-4 w-4 ml-2" />
                {t('action.settings')}
              </Button>
              
              <Button 
                onClick={() => setShowSiteAdmin(true)}
                variant="outline"
                className="border-2 text-white transition-all duration-300 hover:scale-105"
                style={{borderColor: 'var(--brand-orange)', backgroundColor: 'var(--brand-orange-light)'}}
              >
                <Users className="h-4 w-4 ml-2" />
                {t('action.siteAdmin')}
              </Button>
              
              <Button 
                onClick={() => setShowCacheManager(true)}
                variant="outline"
                className="border-2 text-white transition-all duration-300 hover:scale-105"
                style={{borderColor: 'var(--brand-gray)', backgroundColor: 'var(--brand-gray-light)'}}
              >
                <Download className="h-4 w-4 ml-2" />
                {t('إدارة التخزين المؤقت')}
              </Button>
            </div>
            
            <div className="flex items-center space-x-3 space-x-reverse">
              <Button 
                onClick={() => setShowAddAwardPoint(true)}
                variant="outline"
                className="border-2 text-white transition-all duration-300 hover:scale-105"
                style={{borderColor: 'var(--brand-orange)', backgroundColor: 'var(--brand-orange-light)'}}
              >
                <Award className="h-4 w-4 ml-2" />
                {t('action.addAwardPoint')}
              </Button>
              
            <Button 
              onClick={() => setShowAddInitiative(true)}
              className="text-white shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-300 enhanced-button"
              style={{backgroundColor: 'var(--brand-orange-dark)'}}
            >
                <Plus className="h-4 w-4 ml-2" />
                {t('action.addInitiative')}
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Enhanced Navigation Tabs */}
      <div className="bg-white border-b border-gray-200 shadow-sm">
        <div className="container mx-auto px-6 py-3">
          <div className="enhanced-tabs">
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabsList className="grid w-full grid-cols-6 bg-transparent p-0 h-auto gap-2">
                <TabsTrigger 
                  value="award"
                  className="enhanced-tab data-[state=active]:text-white data-[state=active]:shadow-lg hover:bg-white/50 transition-all duration-300"
                  style={activeTab === 'award' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  <Award className="h-5 w-5 ml-2" />
                  {t('nav.award')}
                </TabsTrigger>
                <TabsTrigger 
                  value="details"
                  className="enhanced-tab data-[state=active]:text-white data-[state=active]:shadow-lg hover:bg-white/50 transition-all duration-300"
                  style={activeTab === 'details' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  <Users className="h-5 w-5 ml-2" />
                  {t('nav.details')}
                </TabsTrigger>
                <TabsTrigger 
                  value="financial"
                  className="enhanced-tab data-[state=active]:text-white data-[state=active]:shadow-lg hover:bg-white/50 transition-all duration-300"
                  style={activeTab === 'financial' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  <Download className="h-5 w-5 ml-2" />
                  {t('nav.financial')}
                </TabsTrigger>
                <TabsTrigger 
                  value="performance"
                  className="enhanced-tab data-[state=active]:text-white data-[state=active]:shadow-lg hover:bg-white/50 transition-all duration-300"
                  style={activeTab === 'performance' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  <TrendingUp className="h-5 w-5 ml-2" />
                  {t('nav.performance')}
                </TabsTrigger>
                <TabsTrigger 
                  value="overview" 
                  className="enhanced-tab data-[state=active]:text-white data-[state=active]:shadow-lg hover:bg-white/50 transition-all duration-300"
                  style={activeTab === 'overview' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  <BarChart3 className="h-5 w-5 ml-2" />
                  {t('nav.overview')}
                </TabsTrigger>
                <TabsTrigger 
                  value="data-management" 
                  className="enhanced-tab data-[state=active]:text-white data-[state=active]:shadow-lg hover:bg-white/50 transition-all duration-300"
                  style={activeTab === 'data-management' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  <Users className="h-5 w-5 ml-2" />
                  {t('nav.dataManagement')}
                </TabsTrigger>
              </TabsList>
            </Tabs>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <main className="container mx-auto px-6 py-6">
        {/* Notification System */}
        <NotificationSystem statistics={statistics} onDataUpdate={handleDataUpdate} />
        
        <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-8">

          <TabsContent value="award" className="space-y-6">
            <AwardTab statistics={statistics} onDataUpdate={handleDataUpdate} />
          </TabsContent>

          <TabsContent value="details" className="space-y-6">
            <DetailsTab statistics={statistics} onDataUpdate={handleDataUpdate} />
          </TabsContent>

          <TabsContent value="financial" className="space-y-6">
            <FinancialTab statistics={statistics} onDataUpdate={handleDataUpdate} />
          </TabsContent>

          <TabsContent value="performance" className="space-y-6">
            <PerformanceTab statistics={statistics} onDataUpdate={handleDataUpdate} />
          </TabsContent>

          <TabsContent value="overview" className="space-y-6">
            <OverviewTab statistics={statistics} onDataUpdate={handleDataUpdate} />
          </TabsContent>

          <TabsContent value="data-management" className="space-y-6">
            <Tabs defaultValue="data-entry" className="space-y-6">
              <TabsList className="grid w-full grid-cols-2">
                <TabsTrigger value="data-entry">إدارة البيانات</TabsTrigger>
                <TabsTrigger value="evaluation">تقييم الإدارات</TabsTrigger>
              </TabsList>
              
              <TabsContent value="data-entry">
                <ComprehensiveDataManagement 
                  open={true} 
                  onOpenChange={() => {}} 
                  onDataUpdate={handleDataUpdate}
                  embedded={true}
                />
              </TabsContent>
              
              <TabsContent value="evaluation">
                <DepartmentEvaluation 
                  statistics={statistics} 
                  onDataUpdate={handleDataUpdate}
                />
              </TabsContent>
            </Tabs>
          </TabsContent>
        </Tabs>
      </main>

      {/* Dialogs */}
      <AddInitiativeDialog 
        open={showAddInitiative} 
        onOpenChange={setShowAddInitiative}
        onSuccess={handleDataUpdate}
      />
      
      <AddAwardPointDialog 
        open={showAddAwardPoint} 
        onOpenChange={setShowAddAwardPoint}
        onSuccess={handleDataUpdate}
      />
      
      <EnhancedImportExport 
        open={showImportExport} 
        onOpenChange={setShowImportExport}
        onSuccess={handleDataUpdate}
      />
      
      <AdvancedSettings 
        open={showAdvancedSettings} 
        onOpenChange={setShowAdvancedSettings}
      />
      
      <EnhancedDataManagement 
        open={showDataManagement} 
        onOpenChange={setShowDataManagement}
        onDataUpdate={handleDataUpdate}
      />
      
      <SiteAdministration 
        open={showSiteAdmin} 
        onOpenChange={setShowSiteAdmin}
      />

      {/* Cache Manager Dialog */}
      {showCacheManager && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-auto">
            <div className="p-4 border-b flex items-center justify-between">
              <h2 className="text-lg font-semibold">{t('إدارة التخزين المؤقت')}</h2>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowCacheManager(false)}
              >
                ✕
              </Button>
            </div>
            <div className="p-4">
              <CacheManager onCacheUpdate={handleDataUpdate} />
            </div>
          </div>
        </div>
      )}

      {/* Offline Status and PWA Components */}
      <EnhancedOfflineStatus />
      <PWAInstallPrompt />
    </div>
  );
}

function App() {
  return (
    <LanguageProvider>
      <AppContent />
    </LanguageProvider>
  );
}

export default App;
